package catalog

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"

	"github.com/yoosuf/ae.sh/internal/util"
	"github.com/yoosuf/ae.sh/internal/version"
)

// ExportPlugin writes plugin-shaped bundles for local development. Plugins are
// not published by this command; enable them with the provider's own CLI after
// reviewing the generated files.
func ExportPlugin(cat Catalogue, outDir, provider string) (string, error) {
	if provider != "claude" && provider != "codex" {
		return "", fmt.Errorf("unsupported plugin provider %q", provider)
	}
	base := filepath.Join(outDir, provider)
	skillsDir := filepath.Join(base, "skills")
	if err := util.EnsureDir(skillsDir); err != nil {
		return "", err
	}
	for _, slug := range cat.Slugs() {
		skill, _ := cat.BySlug(slug)
		dir := filepath.Join(skillsDir, slug)
		if err := util.EnsureDir(dir); err != nil {
			return "", err
		}
		raw, err := os.ReadFile(skill.Path)
		if err != nil {
			return "", err
		}
		if err := os.WriteFile(filepath.Join(dir, "SKILL.md"), raw, 0o644); err != nil {
			return "", err
		}
		if provider == "codex" {
			meta := map[string]any{
				"interface": map[string]any{
					"display_name":      skill.Slug,
					"short_description": truncate(skill.Description, 120),
				},
				"policy": map[string]any{"allow_implicit_invocation": true},
			}
			encoded, err := yaml.Marshal(meta)
			if err != nil {
				return "", err
			}
			agentsDir := filepath.Join(dir, "agents")
			if err := util.EnsureDir(agentsDir); err != nil {
				return "", err
			}
			if err := os.WriteFile(filepath.Join(agentsDir, "openai.yaml"), encoded, 0o644); err != nil {
				return "", err
			}
		}
	}
	pluginDir := filepath.Join(base, ".claude-plugin")
	if err := util.EnsureDir(pluginDir); err != nil {
		return "", err
	}
	manifest := map[string]any{
		"name":        "ae-" + provider,
		"version":     version.Version,
		"description": "Agentic Engineering skills for " + provider,
		"author": map[string]string{
			"name": "AE maintainers",
		},
	}
	raw, err := json.MarshalIndent(manifest, "", "  ")
	if err != nil {
		return "", err
	}
	if err := os.WriteFile(filepath.Join(pluginDir, "plugin.json"), append(raw, '\n'), 0o644); err != nil {
		return "", err
	}
	readme := fmt.Sprintf("# AE plugin bundle (%s)\n\nGenerated by `ae skills export` from the canonical catalogue. Validate with your provider CLI before enabling. Do not hand-edit generated skill files.\n", provider)
	if err := os.WriteFile(filepath.Join(base, "README.md"), []byte(readme), 0o644); err != nil {
		return "", err
	}
	return base, nil
}
